INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 47, 'theory', 'Quiz: memory, garbage collection, and weak references');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 47, 0, 'When is an object with no cyclic references destroyed in CPython?', '["When the garbage collector runs next", "When the program exits", "Immediately, as soon as its reference count becomes zero", "A minute after its last use"]', 2, 'Reference counting frees the object immediately; the collector is needed only for cycles.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 47, 1, 'What is the cyclic garbage collector (the gc module) for?', '["To free any objects instead of reference counting", "To find and free unreachable cycles of objects", "To speed up the program", "To close files"]', 1, 'In a cycle the counts never drop to zero, so a separate mechanism is needed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 47, 2, 'What does weakref.ref(obj)() return if the object has already been deleted?', '["None", "A ReferenceError exception", "An empty object", "The last value"]', 0, 'Calling a weak reference gives the object if it is alive, or None.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 47, 3, 'Why shouldn''t you rely on __del__ to close resources?', '["It doesn''t work in CPython", "The moment of the call depends on the implementation, and exceptions in it are only printed", "It is too fast", "It is called twice"]', 1, 'Use context managers and weakref.finalize.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 47, 4, 'How does deepcopy differ from copy?', '["Speed", "deepcopy also copies nested objects, remembering what it has already copied in memo", "deepcopy copies only keys", "No difference for lists"]', 1, 'memo lets deepcopy handle cyclic structures correctly.');
